mapper.select:
SELECT ticket.order_status, ticket.price, ticket.purchase_time, screening.show_time, screening.end_time, ticket.seat_number, movie.mname, hall.hname, ticket.tid FROM ticket INNER JOIN screening ON ticket.sid = screening.sid INNER JOIN movie ON screening.mid = movie.mid INNER JOIN hall ON screening.hid = hall.hid WHERE ticket.uid = #{portalVo.id}
AND ticket.order_status = #{portalVo.orderStatus}
AND ticket.is_deleted = 0 ORDER BY purchase_time DESC
